import{_ as d,o,c,aO as t}from"./chunks/framework.vjUPZZJn.js";const s=JSON.parse('{"title":"vim 基本操作入门：模式、光标移动与常用命令","description":"","frontmatter":{"date":"2026-11-23T10:40:00.000Z","title":"vim 基本操作入门：模式、光标移动与常用命令","source":[["1-知识/工具/Linux环境/vim基本操作"]],"tags":["工具","教程手册","vim","Linux"],"categories":["工具"],"permalink":"/pages/4a40fd"},"headers":[],"relativePath":"工具/vim 基本操作入门：模式、光标移动与常用命令.md","filePath":"工具/vim 基本操作入门：模式、光标移动与常用命令.md","lastUpdated":1795412618000}'),i={name:"工具/vim 基本操作入门：模式、光标移动与常用命令.md"};function a(l,e,r,n,h,p){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="vim-基本操作入门-模式、光标移动与常用命令" tabindex="-1">vim 基本操作入门：模式、光标移动与常用命令 <a class="header-anchor" href="#vim-基本操作入门-模式、光标移动与常用命令" aria-label="Permalink to &quot;vim 基本操作入门：模式、光标移动与常用命令&quot;">​</a></h1> <p>服务器上改一行配置、看一段日志，往往来不及也没有图形编辑器可用，vim 是这类场景里最稳的选择——但它的模式机制对新手并不直觉。本文是最小够用的入门：四种模式与切换方式、光标移动按键、以及日常最高频的编辑、查找替换与保存退出命令。读完可以在终端里不碰鼠标完成一次小改动。</p> <h2 id="模式与切换" tabindex="-1">模式与切换 <a class="header-anchor" href="#模式与切换" aria-label="Permalink to &quot;模式与切换&quot;">​</a></h2> <p>vim 底部状态栏会提示当前模式，常用的有四种：</p> <table tabindex="0"><thead><tr><th>模式</th> <th>状态栏显示</th> <th>用途</th></tr></thead> <tbody><tr><td>普通模式</td> <td><code>--NORMAL--</code></td> <td>移动光标、执行命令，默认所在模式</td></tr> <tr><td>插入模式</td> <td><code>--INSERT--</code></td> <td>输入文本</td></tr> <tr><td>可视模式</td> <td><code>--VISUAL--</code></td> <td>选中文本块</td></tr> <tr><td>命令模式</td> <td><code>--COMMAND--</code></td> <td>执行保存、退出、替换等 <code>:</code> 命令</td></tr></tbody></table> <p>各模式之间最常用的切换路径：</p> <ul><li>普通模式 → 插入模式：<code>i</code> 在光标前插入，<code>I</code> 在行首插入，<code>a</code> 在光标后插入（append），<code>A</code> 在行尾插入，<code>o</code> 在下一行新建插入，<code>O</code> 在上一行新建插入</li> <li>普通模式 ↔ 可视模式：<code>v</code></li> <li>普通模式 → 命令模式：<code>:</code></li> <li>任意模式回到普通模式：<code>ESC</code></li></ul> <p>新手最常见的困境是“打开 vim 不知道怎么输入、输完不知道怎么退出”，根源就是没意识到当前在哪个模式：先按 <code>ESC</code> 回普通模式，再决定下一步。</p> <h2 id="光标移动" tabindex="-1">光标移动 <a class="header-anchor" href="#光标移动" aria-label="Permalink to &quot;光标移动&quot;">​</a></h2> <p>以下按键都在<strong>普通模式</strong>下生效。</p> <p>以字符为单位：</p> <ul><li><code>h</code> 左移，<code>j</code> 下移，<code>k</code> 上移，<code>l</code> 右移</li></ul> <p>以单词为单位：</p> <ul><li><code>w</code> 跳到下一个单词的开头（word）</li> <li><code>b</code> 光标不在单词开头时跳到本单词开头，否则跳到上一个单词开头（begin）</li> <li><code>e</code> 光标不在单词结尾时跳到本单词结尾，否则跳到下一个单词结尾（end）</li> <li><code>ge</code> 跳到上一个单词的结尾</li></ul> <p>行内与全文跳转：</p> <ul><li><code>0</code> 跳到行首第一列，<code>^</code> 跳到行首第一个非空白字符，<code>$</code> 跳到行尾</li> <li><code>gg</code> 跳到文件首行，<code>G</code> 跳到文件末行</li> <li><code>:{n}</code> 或 <code>{n}G</code> 跳到第 n 行（如 <code>:42</code> 或 <code>42G</code>）</li></ul> <h2 id="常用编辑命令" tabindex="-1">常用编辑命令 <a class="header-anchor" href="#常用编辑命令" aria-label="Permalink to &quot;常用编辑命令&quot;">​</a></h2> <p>普通模式下：</p> <ul><li><code>dd</code> 删除（剪切）当前行，<code>ndd</code> 删除 n 行（如 <code>3dd</code>）</li> <li><code>yy</code> 复制当前行，<code>nyy</code> 复制 n 行</li> <li><code>p</code> 在光标后粘贴，<code>P</code> 在光标前粘贴</li> <li><code>x</code> 删除光标处字符</li> <li><code>u</code> 撤销（undo），<code>Ctrl-r</code> 重做（redo）</li></ul> <h2 id="查找与替换" tabindex="-1">查找与替换 <a class="header-anchor" href="#查找与替换" aria-label="Permalink to &quot;查找与替换&quot;">​</a></h2> <ul><li><code>/{pattern}</code> 向下查找，<code>?{pattern}</code> 向上查找；<code>n</code> 跳到下一个匹配，<code>N</code> 跳到上一个匹配</li> <li><code>:%s/old/new/g</code> 全文替换；加 <code>c</code> 逐个确认：<code>:%s/old/new/gc</code></li></ul> <h2 id="保存与退出" tabindex="-1">保存与退出 <a class="header-anchor" href="#保存与退出" aria-label="Permalink to &quot;保存与退出&quot;">​</a></h2> <p>命令模式（普通模式下按 <code>:</code> 进入）：</p> <ul><li><code>:w</code> 保存</li> <li><code>:q</code> 退出</li> <li><code>:wq</code> 或普通模式下 <code>ZZ</code> 保存并退出</li> <li><code>:q!</code> 不保存强制退出</li></ul> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>vim 的上手门槛集中在模式切换：记住“先 <code>ESC</code> 回普通模式”这一条，插入、选中、命令三种入口（<code>i</code>/<code>v</code>/<code>:</code>）就不会混乱。日常操作记住三组就够用——<code>hjkl</code> 与 <code>w/b/e</code> 移动，<code>dd/yy/p/u</code> 编辑，<code>/:wq/:q!</code> 查找与退出；其余命令用到时再查，不必一次背全。</p>',51)])])}const u=d(i,[["render",a]]);export{s as __pageData,u as default};
